// Unless either policy disables consistent hashing, the hash policies of both are unioned
// irrespective of the merge strategy, with the higher priority policy's entries taking precedence.
func mergeConsistentHash(
	p1, p2 *TrafficPolicy,
	p2Ref *ir.AttachedPolicyRef,
	p2MergeOrigins ir.MergeOrigins,
	opts policy.MergeOptions,
	mergeOrigins ir.MergeOrigins,
	_ TrafficPolicyMergeOpts,
) {
	const fieldName = "consistentHash"

	p1Field := p1.spec.consistentHash
	p2Field := p2.spec.consistentHash
	if p2Field == nil {
		return
	}
